}

export function disposeMesh(gl: WebGL2RenderingContext, mesh: ChunkMesh | null): void {
  if (!mesh) return;
  for (const g of [mesh.solid, mesh.translucent]) {
    if (!g) continue;
    gl.deleteVertexArray(g.vao);
    gl.deleteBuffer(g.vbo);
    gl.deleteBuffer(g.ibo);
  }
}

