private pack(x: number, y: number, z: number): number {
  const lx = x - this.minWorldX;
  const lz = z - this.minWorldZ;
  const ly = y - WORLD_MIN_Y;
  return (lx & 511) | ((lz & 511) << Z_SHIFT) | ((ly & 511) << Y_SHIFT);
