  this.yaw = yaw;
  this.pitch = pitch;
  this.frameTime = elapsed;
  const aspect = gl.drawingBufferWidth / Math.max(1, gl.drawingBufferHeight);
  perspective(this.proj, (this.fov * Math.PI) / 180, aspect, 0.05, 512);

