1	// Vanilla-style world particles: block-break terrain chips with gravity and floor friction.
2	import type { LoadedAssets } from './assets.js';
3	import type { BlockRegistry } from './blocks.js';
4	import type { World } from './world.js';
5	import { ShaderProgram } from './gl.js';
6	import type { Mat4 } from './math.js';
7	
8	const VS = `#version 300 es
9	layout(location = 0) in vec3 aPos;
10	layout(location = 1) in vec2 aUV;
11	layout(location = 2) in float aLayer;
12	layout(location = 3) in vec3 aColor;
13	layout(location = 4) in vec2 aLight;
14	uniform mat4 uViewProj;
15	out vec2 vUV;
16	out float vLayer;
17	out vec3 vColor;
18	out vec2 vLight;
19	void main() {
20	  vUV = aUV;
21	  vLayer = aLayer;
22	  vColor = aColor;
23	  vLight = aLight;
24	  gl_Position = uViewProj * vec4(aPos, 1.0);
25	}`;
26	
27	const FS = `#version 300 es
28	precision highp float;
29	in vec2 vUV;
30	in float vLayer;
31	in vec3 vColor;
32	in vec2 vLight;
33	uniform highp sampler2DArray uTex;
34	uniform vec3 uSkyColor;
35	uniform vec3 uBlockColor;
36	uniform float uSkyFactor;
37	out vec4 outColor;
38	void main() {
39	  vec4 t = texture(uTex, vec3(vUV, vLayer));
40	  if (t.a < 0.1) discard;
41	  float sky = vLight.x / (4.0 - 3.0 * vLight.x);
42	  float blk = vLight.y / (4.0 - 3.0 * vLight.y);
43	  vec3 light = vec3(0.045) + uSkyColor * sky * uSkyFactor + uBlockColor * blk;
44	  outColor = vec4(t.rgb * vColor * light, 1.0);
45	}`;
46	
47	const STRIDE = 11;
48	const GRAVITY = 16;
49	const MAX_PARTICLES = 3000;
50	
51	interface Particle {
52	  x: number; y: number; z: number;
53	  vx: number; vy: number; vz: number;
54	  life: number; maxLife: number;
55	  size: number;
56	  layer: number;
57	  u0: number; v0: number;
58	  r: number; g: number; b: number;
59	}
60	
61	export class ParticleSystem {
62	  private particles: Particle[] = [];
63	  private program: ShaderProgram;
64	  private vao: WebGLVertexArrayObject;
65	  private vbo: WebGLBuffer;
66	  private data = new Float32Array(MAX_PARTICLES * 6 * STRIDE);
67	  private gl: WebGL2RenderingContext;
68	  enabled = true;
69	
70	  constructor(gl: WebGL2RenderingContext, private assets: LoadedAssets, private rocks: BlockRegistry, private world: World) {
71	    this.gl = gl;
72	    this.program = new ShaderProgram(gl, VS, FS);
73	    this.vao = gl.createVertexArray()!;
74	    this.vbo = gl.createBuffer()!;
75	    gl.bindVertexArray(this.vao);
76	    gl.bindBuffer(gl.ARRAY_BUFFER, this.vbo);
77	    gl.bufferData(gl.ARRAY_BUFFER, this.data.byteLength, gl.DYNAMIC_DRAW);
78	    const s = STRIDE * 4;
79	    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, s, 0);
80	    gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, s, 12);
81	    gl.enableVertexAttribArray(2); gl.vertexAttribPointer(2, 1, gl.FLOAT, false, s, 20);
82	    gl.enableVertexAttribArray(3); gl.vertexAttribPointer(3, 3, gl.FLOAT, false, s, 24);
83	    gl.enableVertexAttribArray(4); gl.vertexAttribPointer(4, 2, gl.FLOAT, false, s, 36);
84	    gl.bindVertexArray(null);
85	  }
86	
87	  get count(): number { return this.particles.length; }
88	
89	  clear(): void { this.particles.length = 0; }
90	
91	  /** Spawns the chips vanilla throws out when a block is destroyed. */
92	  destroyBlock(x: number, y: number, z: number, id: number): void {
93	    if (!this.enabled || id === 0) return;
94	    const def = this.rocks.get(id);
95	    if (!def || def.custom) return;
96	    const top = def.quads.find(q => q.d === 1) ?? def.quads[0];
97	    if (!top) return;
98	    const tint = this.rocks.tintMode[id] === 0 ? [1, 1, 1] : def.tintColor;
99	    const solid = this.rocks.solid[id] === 1;
100	    const n = solid ? 14 : 6;
101	    for (let i = 0; i < n; i++) {
102	      const size = 0.07 + Math.random() * 0.055;
103	      this.push({
104	        x: x + 0.15 + Math.random() * 0.7,
105	        y: y + 0.15 + Math.random() * 0.7,
106	        z: z + 0.15 + Math.random() * 0.7,
107	        vx: (Math.random() - 0.5) * 2.6,
108	        vy: Math.random() * 3.4 + 0.6,
109	        vz: (Math.random() - 0.5) * 2.6,
110	        life: 0.75 + Math.random() * 0.75,
111	        maxLife: 1.5,
112	        size,
113	        layer: top.layer,
114	        // A 4x4 pixel window at a random offset, like vanilla's TerrainParticle.
115	        u0: (3 + Math.floor(Math.random() * 3)) / 16,
116	        v0: (3 + Math.floor(Math.random() * 3)) / 16,
117	        r: tint[0], g: tint[1], b: tint[2],
118	      });
119	    }
120	  }
121	
122	  /** A short puff of the block's own material, used for impacts and landings. */
123	  hitBlock(x: number, y: number, z: number, id: number, nx: number, ny: number, nz: number, amount = 4): void {
124	    if (!this.enabled || id === 0) return;
125	    const def = this.rocks.get(id);
126	    const quad = def.quads.find(q => q.d === 1) ?? def.quads[0];
127	    if (!quad) return;
128	    for (let i = 0; i < amount; i++) {
129	      this.push({
130	        x: x + 0.5 + nx * 0.55 + (Math.random() - 0.5) * 0.5,
131	        y: y + 0.5 + ny * 0.55 + (Math.random() - 0.5) * 0.5,
132	        z: z + 0.5 + nz * 0.55 + (Math.random() - 0.5) * 0.5,
133	        vx: nx * 1.4 + (Math.random() - 0.5) * 1.2,
134	        vy: ny * 1.4 + Math.random() * 1.6,
135	        vz: nz * 1.4 + (Math.random() - 0.5) * 1.2,
136	        life: 0.35 + Math.random() * 0.35,
137	        maxLife: 0.7,
138	        size: 0.05 + Math.random() * 0.04,
139	        layer: quad.layer,
140	        u0: (3 + Math.floor(Math.random() * 3)) / 16,
141	        v0: (3 + Math.floor(Math.random() * 3)) / 16,
142	        r: 1, g: 1, b: 1,
143	      });
144	    }
145	  }
146	
147	  private push(p: Particle): void {
148	    if (this.particles.length >= MAX_PARTICLES) this.particles.shift();
149	    this.particles.push(p);
150	  }
151	
152	  tick(dt: number): void {
153	    const list = this.particles;
154	    for (let i = list.length - 1; i >= 0; i--) {
155	      const p = list[i];
156	      p.life -= dt;
157	      if (p.life <= 0) { list.splice(i, 1); continue; }
158	      p.vy -= GRAVITY * dt;
159	      let nx = p.x + p.vx * dt;
160	      let ny = p.y + p.vy * dt;
161	      const nz = p.z + p.vz * dt;
162	      if (this.solidAt(nx, p.y, p.z)) nx = p.x;
163	      if (!this.solidAt(p.x, p.y, nz)) { p.z = nz; }
164	      if (this.solidAt(p.x, ny, p.z)) {
165	        if (p.vy < 0) {
166	          ny = Math.floor(ny) + 1 + p.size * 0.5;
167	          p.vx *= 0.62;
168	          p.vz *= 0.62;
169	          p.vy = 0;
170	        } else {
171	          ny = p.y;
172	          p.vy = 0;
173	        }
174	      }
175	      p.x = nx; p.y = ny; p.z = nz;
176	      p.vx *= 1 - 1.1 * dt;
177	      p.vz *= 1 - 1.1 * dt;
178	    }
179	  }
180	
181	  private solidAt(x: number, y: number, z: number): boolean {
182	    const id = this.world.getBlock(Math.floor(x), Math.floor(y), Math.floor(z));
183	    return id !== 0 && this.rocks.solid[id] === 1;
184	  }
185	
186	  render(gl: WebGL2RenderingContext, viewProj: Mat4, eye: [number, number, number],
187	    skyColor: [number, number, number], blockColor: [number, number, number], skyFactor: number): void {
188	    if (!this.particles.length) return;
189	    // Camera basis rows from the view-projection matrix give a billboard aligned to the screen.
