86	      ['Natural Blocks', ['grass_block', 'dirt', 'coarse_dirt', 'rooted_dirt', 'podzol', 'sand', 'red_sand', 'gravel', 'clay',
87	        'oak_log', 'birch_log', 'spruce_log', 'oak_leaves', 'birch_leaves', 'spruce_leaves', 'coal_ore', 'iron_ore', 'copper_ore',
88	        'gold_ore', 'diamond_ore', 'emerald_ore', 'bedrock', 'snow', 'moss_block', 'cactus', 'short_grass', 'fern', 'dead_bush',
89	        'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy', 'allium', 'lily_of_the_valley', 'sulfur_spike', 'water', 'lava']],
90	      ['Functional Blocks', ['crafting_table', 'bookshelf', 'torch', 'lantern', 'glowstone', 'sea_lantern']],
