133	  }
134	
135	  clearCarried(): void {
136	    this.carriedId = 0;
137	  }
138	
139	  inventoryScroll(delta: number): void {
140	    if (!this.inventoryOpen) return;
141	    const items = this.activeCategory().items;
142	    const max = Math.max(0, Math.ceil(items.length / 9) - 5);
