158	  setMouse(cssX: number, cssY: number): void {
159	    this.mouseCss.x = cssX;
160	    this.mouseCss.y = cssY;
161	  }
162	
163	  hotbarHit(cssX: number, cssY: number): number {
164	    const gx = cssX / this.scale;
165	    const gy = cssY / this.scale;
166	    const hotbarX = Math.floor((this.guiW - 182) / 2);
167	    const hotbarY = this.guiH - 22;
168	    if (gx < hotbarX || gx >= hotbarX + 182 || gy < hotbarY - 2 || gy >= hotbarY + 22) return -1;
169	    return clamp(Math.floor((gx - hotbarX) / 20), 0, 8);
