174	    this.noticeUntil = performance.now() + 1600;
175	  }
176	
177	  private creativeLayout() {
178	    const cols = 9, rows = 5, slot = 18, panelW = 195, panelH = 136;
179	    const x = Math.floor((this.guiW - panelW) / 2);
180	    const y = Math.floor((this.guiH - panelH) / 2);
181	    return {
182	      cols, rows, slot, w: panelW, h: panelH, x, y,
183	      gridX: x + 9, gridY: y + 18, hotbarY: y + 112,
