188	    if (!name) return null;
189	    const def = this.rocks.byName.get(name);
190	    return def ? this.blockIcon(def) : null;
191	  }
192	
193	  private tabRects(): { cat: number; x: number; y: number; w: number; h: number; top: boolean; index: number }[] {
194	    const L = this.creativeLayout();
195	    const rects: { cat: number; x: number; y: number; w: number; h: number; top: boolean; index: number }[] = [];
196	    const tops = this.categories.filter(c => c.top);
197	    for (let i = 0; i < tops.length; i++) {
198	      rects.push({ cat: this.categories.indexOf(tops[i]), x: L.x + 7 + i * 26, y: L.y - 28, w: 26, h: 32, top: true, index: tops[i].index });
199	    }
200	    const bottoms = this.categories.filter(c => !c.top);
201	    for (let i = 0; i < bottoms.length; i++) {
202	      rects.push({ cat: this.categories.indexOf(bottoms[i]), x: L.x + 6 + i * 26, y: L.y + L.h - 4, w: 26, h: 32, top: false, index: bottoms[i].index });
203	    }
204	    return rects;
205	  }
206	
207	  private closeRect() {
208	    const L = this.creativeLayout();
209	    return { x: L.x + L.w - 18, y: L.y + L.h + 2, w: 14, h: 14 };
210	  }
211	
212	  inventoryHit(cssX: number, cssY: number): { block: number } | { hotbar: number } | { category: number } | { close: true } | { scroll: true } | null {
213	    if (!this.inventoryOpen) return null;
214	    const gx = cssX / this.scale, gy = cssY / this.scale;
215	    const L = this.creativeLayout();
216	    const touchUi = (navigator.maxTouchPoints || 0) > 0;
217	    if (touchUi) {
218	      const c = this.closeRect();
219	      if (gx >= c.x && gx < c.x + c.w && gy >= c.y && gy < c.y + c.h) return { close: true };
220	    }
221	    for (const t of this.tabRects()) {
222	      if (gx >= t.x && gx < t.x + t.w && gy >= t.y && gy < t.y + t.h) {
223	        this.invCategory = t.cat;
224	        this.invScrollRow = 0;
225	        this.survivalView = this.categories[t.cat]?.name === 'Survival Inventory';
226	        this.carriedId = 0;
227	        return { category: t.cat };
228	      }
229	    }
230	    if (gx >= L.x && gx < L.x + L.w && gy >= L.y && gy < L.y + L.h) {
231	      if (this.survivalView) {
232	        if (gx >= L.x + 173 && gy >= L.y + 112) return { close: true };
233	        const slot = Math.floor((gx - (L.x + 9)) / L.slot);
234	        if (slot >= 0 && slot < 9 && gy >= L.hotbarY && gy < L.hotbarY + 18) return { hotbar: slot };
235	        return null;
236	      }
237	      const col = Math.floor((gx - L.gridX) / L.slot);
238	      const row = Math.floor((gy - L.gridY) / L.slot);
239	      if (col >= 0 && col < 9 && row >= 0 && row < 5) {
240	        const items = this.activeCategory().items;
241	        const idx = this.invScrollRow * 9 + row * 9 + col;
242	        if (idx < items.length) {
243	          this.carriedId = items[idx].id;
244	          return { block: items[idx].id };
245	        }
246	      }
247	      const slot = Math.floor((gx - (L.x + 9)) / L.slot);
248	      if (slot >= 0 && slot < 9 && gy >= L.hotbarY && gy < L.hotbarY + 18) return { hotbar: slot };
249	      if (gx >= L.x + 175 && gx < L.x + 187 && gy >= L.y + 18 && gy < L.y + 108) {
250	        const max = Math.max(0, Math.ceil(this.activeCategory().items.length / 9) - 5);
251	        if (max > 0) {
252	          this.invScrollRow = clamp(Math.round(((gy - (L.y + 18)) / 90) * max), 0, max);
253	          return { scroll: true };
254	        }
255	      }
256	      return null;
257	    }
258	    return null;
259	  }
260	
261	  private drawInventory(player: Player): void {
262	    const { ctx, assets } = this;
263	    const L = this.creativeLayout();
264	    const gx = this.mouseCss.x / this.scale;
265	    const gy = this.mouseCss.y / this.scale;
266	    const category = this.activeCategory();
267	    const items = category.items;
268	    const maxScroll = Math.max(0, Math.ceil(items.length / 9) - 5);
269	    this.invScrollRow = clamp(this.invScrollRow, 0, maxScroll);
270	
271	    const panel = this.survivalView ? assets.gui.creativeInventory : assets.gui.creativeItems;
272	    if (panel) ctx.drawImage(panel, 0, 0, 195, 136, L.x, L.y, 195, 136);
273	    else {
274	      ctx.fillStyle = '#c6c6c6';
275	      ctx.fillRect(L.x, L.y, L.w, L.h);
276	    }
277	
278	    // Official tab sprites sit around the panel; the active tab is drawn last.
279	    this.hoverTab = -1;
280	    const tabList = this.tabRects().sort((a, b) => Number(a.cat === this.invCategory) - Number(b.cat === this.invCategory));
281	    for (const t of tabList) {
282	      const selected = t.cat === this.invCategory;
283	      const key = `${t.top ? 'tabTop' : 'tabBottom'}${selected ? 'Selected' : 'Unselected'}${t.index}`;
284	      const tab = assets.gui[key];
285	      if (tab) ctx.drawImage(tab, t.x, t.y, 26, 32);
286	      const icon = this.iconForName(this.categories[t.cat]?.icon ?? null);
287	      if (icon) ctx.drawImage(icon, t.x + 5, t.y + 8, 16, 16);
288	      if (gx >= t.x && gx < t.x + t.w && gy >= t.y && gy < t.y + t.h) this.hoverTab = t.cat;
289	    }
290	
291	    const first = this.invScrollRow * 9;
292	    let hovered: BlockDef | null = null;
293	    if (!this.survivalView) {
294	      for (let i = 0; i < 45; i++) {
295	        const idx = first + i;
296	        if (idx >= items.length) break;
297	        const col = i % 9, row = (i / 9) | 0;
298	        const sx = L.gridX + col * 18, sy = L.gridY + row * 18;
299	        const hov = gx >= sx && gx < sx + 18 && gy >= sy && gy < sy + 18;
300	        if (hov) {
301	          ctx.fillStyle = 'rgba(255,255,255,0.55)';
302	          ctx.fillRect(sx + 1, sy + 1, 16, 16);
303	          hovered = items[idx];
304	        }
305	        const icon = this.blockIcon(items[idx]);
306	        ctx.drawImage(icon, sx + 1, sy + 1, 16, 16);
307	      }
308	    }
309	
310	    // Player hotbar row in the creative panel.
311	    for (let i = 0; i < 9; i++) {
312	      const def = player.hotbar[i];
313	      if (!def) continue;
314	      const sx = L.x + 9 + i * 18, sy = L.hotbarY;
315	      const icon = this.blockIcon(def);
316	      ctx.drawImage(icon, sx + 1, sy + 1, 16, 16);
317	      if (gx >= sx && gx < sx + 18 && gy >= sy && gy < sy + 18) hovered = def;
318	    }
319	    const selX = L.x + 9 + player.selected * 18;
320	    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
321	    ctx.lineWidth = 1;
322	    ctx.strokeRect(selX + 0.5, L.hotbarY + 0.5, 17, 17);
323	
324	    // Scrollbar.
325	    if (!this.survivalView && maxScroll > 0) {
326	      const frac = this.invScrollRow / maxScroll;
327	      const scroller = assets.gui.creativeScroller;
328	      if (scroller) ctx.drawImage(scroller, L.x + 175, L.y + 18 + Math.round(frac * 75), 12, 15);
329	    }
330	
331	    if (!this.survivalView && (navigator.maxTouchPoints || 0) > 0) {
332	      const c = this.closeRect();
333	      ctx.fillStyle = '#c6c6c6';
334	      ctx.fillRect(c.x, c.y, c.w, c.h);
335	      ctx.fillStyle = '#ffffff';
336	      ctx.fillRect(c.x, c.y, c.w, 1);
337	      ctx.fillStyle = '#555555';
338	      ctx.fillRect(c.x, c.y + c.h - 1, c.w, 1);
339	      assets.font.drawCentered(ctx, 'x', c.x + c.w / 2, c.y + 3, '#3f3f3f', false);
340	    }
341	
342	    const carried = this.carriedId ? this.rocks.get(this.carriedId) : null;
343	    if (carried) {
344	      const icon = this.blockIcon(carried);
345	      ctx.drawImage(icon, gx - 8, gy - 8, 16, 16);
346	    }
347	
348	    let tip = this.survivalView ? '' : (hovered ? titleCase(hovered.name) : '');
349	    if (!tip && this.hoverTab >= 0) tip = this.categories[this.hoverTab]?.name ?? '';
350	    if ((navigator.maxTouchPoints || 0) > 0) tip = '';
351	    if (tip) {
352	      const w = assets.font.width(tip) + 8;
353	      const x = clamp(gx + 10, 0, this.guiW - w);
354	      const y = clamp(gy - 14, 0, this.guiH - 14);
355	      ctx.fillStyle = 'rgba(16,0,16,0.94)';
356	      ctx.fillRect(x, y, w, 13);
357	      ctx.strokeStyle = 'rgba(80,0,255,0.9)';
358	      ctx.lineWidth = 1;
359	      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, 12);
360	      assets.font.draw(ctx, tip, x + 4, y + 3, COLORS.white, false);
361	    }
362	  }
363	
364	  render(state: {
365	    started: boolean;
366	    paused: boolean;
367	    player: Player;
368	    fps: number;
369	    ticks: number;
370	    debug: boolean;
371	    underwater: boolean;
372	    renderer: Renderer;
373	    elapsed: number;
374	    inventoryOpen: boolean;
375	  }): void {
376	    const { ctx, guiW, guiH } = this;
377	    ctx.setTransform(this.uiScale, 0, 0, this.uiScale, 0, 0);
378	    ctx.imageSmoothingEnabled = false;
379	    ctx.clearRect(0, 0, guiW, guiH);
380	    const player = state.player;

