60	uniform mat4 uLightVP;
61	uniform float uShadowStrength;
62	uniform vec3 uSunDir;
63	uniform vec3 uSunColor;
64	uniform vec3 uSkyTopColor;
65	uniform vec3 uSkyHorizonColor;
66	uniform float uTime;
