77	out vec4 outColor;
78	
79	float curve(float l) { return l / (4.0 - 3.0 * l); }
80	vec3 notGamma(vec3 c) {
81	  float m = max(max(c.r, c.g), c.b);
82	  if (m <= 0.0001) return c;
83	  return c * (1.0 - pow(1.0 - m, 4.0)) / m;
84	}
85	float sunShadow(vec3 world, vec3 normal) {
86	  if (uShadowStrength <= 0.0) return 1.0;
87	  vec4 sp = uLightVP * vec4(world + normal * 0.08, 1.0);
88	  vec3 p = sp.xyz / sp.w * 0.5 + 0.5;
89	  if (p.x <= 0.001 || p.x >= 0.999 || p.y <= 0.001 || p.y >= 0.999 || p.z <= 0.0 || p.z >= 1.0) return 1.0;
90	  float ndl = max(dot(normalize(normal), normalize(uSunDir)), 0.0);
91	  float bias = mix(0.0018, 0.0005, ndl);
92	  vec2 texel = 1.0 / vec2(textureSize(uShadowMap, 0));
93	  float lit = 0.0;
94	  for (int y = -1; y <= 1; y++) {
95	    for (int x = -1; x <= 1; x++) {
96	      float d = texture(uShadowMap, p.xy + vec2(float(x), float(y)) * texel).r;
97	      lit += p.z - bias <= d ? 1.0 : 0.0;
98	    }
99	  }
100	  return lit / 9.0;
101	}
102	void main() {
103	  vec4 tex = texture(uTex, vec3(vUv, float(vLayer)));
104	  if (tex.a < uAlphaCutoff) discard;
105	  vec3 texColor = tex.a > 0.0001 ? tex.rgb / tex.a : vec3(0.0);
106	  if (uDebugMode == 1) { outColor = vec4(texColor * vTint, 1.0); return; }
107	  if (uDebugMode == 2) { outColor = vec4(vec3(vAo), 1.0); return; }
108	  if (uDebugMode == 3) { outColor = vec4(vNormal * 0.5 + 0.5, 1.0); return; }
109	  float shadow = mix(1.0, sunShadow(vWorld, vNormal), uShadowStrength);
110	  vec3 skyTerm = uSkyLightColor * curve(vLight.x) * uSkyFactor * mix(0.32, 1.0, shadow);
111	  vec3 light = uAmbientColor
112	    + skyTerm
113	    + uBlockLightColor * curve(vLight.y) * uBlockFactor;
114	  light = clamp(light, 0.0, 1.0);
115	  light = mix(light, notGamma(light), uGamma);
116	  vec3 c = texColor * vTint * light * vShade * vAo;
117	  float alpha = tex.a;
118	  if (uWaterLayer >= 0 && vLayer == uWaterLayer) {
119	    vec2 wuv = vUv * 2.0;
120	    vec2 drift = vec2(uTime * 0.012, uTime * 0.008);
121	    vec2 uvA = wuv + drift;
122	    vec2 uvB = wuv - drift.yx;
123	    float e = 0.045;
124	    float hL = texture(uTex, vec3(uvA - vec2(e, 0.0), float(vLayer))).r;
125	    float hR = texture(uTex, vec3(uvA + vec2(e, 0.0), float(vLayer))).r;
126	    float hD = texture(uTex, vec3(uvB - vec2(0.0, e), float(vLayer))).r;
127	    float hU = texture(uTex, vec3(uvB + vec2(0.0, e), float(vLayer))).r;
128	    vec3 wn = normalize(vec3((hL - hR) * 2.2, 1.0, (hD - hU) * 2.2));
129	    vec3 V = normalize(uCam - vWorld);
130	    float ndv = clamp(dot(wn, V), 0.0, 1.0);
