const FOLIAGE: [number, number, number] = [119 / 255, 171 / 255, 47 / 255];
const WATER: [number, number, number] = [63 / 255, 118 / 255, 228 / 255];
const TINT_GRASS = 1;
const TINT_FOLIAGE = 2;
